namespace PA.Tickets.Domain.Tickets;
public sealed class Ticket
{
 private readonly List<WorkItem> _workItems=[]; private readonly List<TicketDomainEvent> _events=[]; private long? _lastExecutor; private long? _approvalApproverUserId; private bool _approvalRequired; private bool _approved; private int _evidenceCount;
 public long Id{get;private set;} public string Number{get;private set;}=""; public TicketType Type{get;private set;} public TicketStatus Status{get;private set;} public long RequestedBy{get;private set;} public long CreatedBy{get;private set;} public string Subject{get;private set;}=""; public string? Description{get;private set;} public long? ServiceId{get;private set;} public long? CategoryId{get;private set;} public long? SubCategoryId{get;private set;} public long? RequestTypeId{get;private set;} public int? RequestTypeVersion{get;private set;} public long? ClientId{get;private set;} public long? PriorityId{get;private set;} public long? CurrentDepartmentId{get;private set;} public long? CurrentTeamId{get;private set;} public long? CurrentAssignee{get;private set;} public DateTimeOffset CreatedAt{get;private set;} public DateTimeOffset? ResolvedAt{get;private set;} public DateTimeOffset? ClosedAt{get;private set;} public bool ApprovalRequired=>_approvalRequired; public bool Approved=>_approved; public int EvidenceCount=>_evidenceCount; public long? LastExecutor=>_lastExecutor; public IReadOnlyCollection<WorkItem> WorkItems=>_workItems; public IReadOnlyCollection<TicketDomainEvent> UncommittedEvents=>_events;
 public long? ApprovalApproverUserId=>_approvalApproverUserId; public int RowVersion{get;private set;}
 private Ticket(){}
 public static Ticket Create(long id,string number,TicketType type,string subject,string? description,long requester,long creator,DateTimeOffset now){if(id<=0||string.IsNullOrWhiteSpace(number)||string.IsNullOrWhiteSpace(subject)||requester<=0||creator<=0)throw new ArgumentException("Ticket identity, subject, requester, and creator are required.");var t=new Ticket{Id=id,Number=number.Trim(),Type=type,Subject=subject.Trim(),Description=description,RequestedBy=requester,CreatedBy=creator,Status=TicketStatus.New,CreatedAt=now};t.Record("TICKET_CREATED",creator,null,t.Status.ToString(),now,reason:null);return t;}
 public void ApplyCatalogue(long requestTypeId,int requestTypeVersion,int ticketType,long serviceId,long categoryId,long? priorityId,long? departmentId,long? teamId,long? subCategoryId=null){if(requestTypeId<=0||requestTypeVersion<=0||serviceId<=0||categoryId<=0||subCategoryId is <=0)throw new ArgumentException("A valid catalogue configuration is required.");if(!Enum.IsDefined(typeof(TicketType),ticketType))throw new ArgumentException("The catalogue ticket type is invalid.");RequestTypeId=requestTypeId;RequestTypeVersion=requestTypeVersion;Type=(TicketType)ticketType;ServiceId=serviceId;CategoryId=categoryId;SubCategoryId=subCategoryId;PriorityId=priorityId;CurrentDepartmentId=departmentId;CurrentTeamId=teamId;}
 public void SetPriority(long priorityId){if(priorityId<=0)throw new ArgumentOutOfRangeException(nameof(priorityId));PriorityId=priorityId;}
 public void Classify(long serviceId,long categoryId,long requestTypeId,long priorityId,long actor,DateTimeOffset now){EnsureMutable();if(Status is not(TicketStatus.New or TicketStatus.Reopened))throw new InvalidOperationException("Only new or reopened tickets can be classified.");ServiceId=serviceId;CategoryId=categoryId;RequestTypeId=requestTypeId;PriorityId=priorityId;var old=Status;Status=TicketStatus.Classified;Record("TICKET_CLASSIFIED",actor,old.ToString(),Status.ToString(),now);}
 public WorkItem Route(long workItemId,string workItemNumber,long? departmentId,long? teamId,long actor,DateTimeOffset now,long? priorityId=null){EnsureMutable();if(Status is not(TicketStatus.Classified or TicketStatus.Routed or TicketStatus.Reopened))throw new InvalidOperationException("Ticket must be classified before routing.");var item=WorkItem.Create(workItemId,Id,workItemNumber,departmentId,teamId,actor,priorityId??PriorityId);_workItems.Add(item);CurrentDepartmentId=departmentId;CurrentTeamId=teamId;var old=Status;Status=TicketStatus.Routed;Record("WORK_ITEM_CREATED",actor,old.ToString(),Status.ToString(),now,item.Id);return item;}
 public void Assign(WorkItem item,long assignee,long actor,DateTimeOffset now,string? reason=null){EnsureMutable();var changed=item.Assign(assignee,now);CurrentAssignee=assignee;Record(changed?"WORK_ITEM_REASSIGNED":"WORK_ITEM_ASSIGNED",actor,null,assignee.ToString(),now,item.Id,reason);}
 public void RequestApproval(long approver,long actor,DateTimeOffset now){EnsureMutable();if(Status==TicketStatus.PendingApproval)throw new InvalidOperationException("An approval request is already pending.");if(approver<=0||approver==RequestedBy||approver==CreatedBy||approver==_lastExecutor)throw new InvalidOperationException("Segregation of duties prohibits requester, creator, or executor self-approval.");_approvalRequired=true;_approved=false;_approvalApproverUserId=approver;var old=Status;Status=TicketStatus.PendingApproval;Record("APPROVAL_REQUESTED",actor,old.ToString(),Status.ToString(),now);}
 public void Approve(long approver,DateTimeOffset now){EnsureMutable();if(Status!=TicketStatus.PendingApproval||!_approvalRequired||_approved||approver<=0||approver!=_approvalApproverUserId||approver==RequestedBy||approver==CreatedBy||approver==_lastExecutor)throw new InvalidOperationException("Approval is not pending for this approver or violates configured segregation of duties.");_approved=true;var old=Status;Status=TicketStatus.Routed;Record("APPROVAL_APPROVED",approver,old.ToString(),Status.ToString(),now);}
 public void StartExecution(WorkItem item,long executor,long actor,DateTimeOffset now){EnsureMutable();if(_approvalRequired&&!_approved)throw new InvalidOperationException("Approval is required before execution.");Assign(item,executor,actor,now);item.Start(now);_lastExecutor=executor;var old=Status;Status=TicketStatus.InProgress;Record("WORK_ITEM_STARTED",actor,old.ToString(),Status.ToString(),now,item.Id);}
 public void Wait(WorkItem item,string reason,long actor,DateTimeOffset now)=>Wait(item,reason,null,null,null,actor,now);
 public void Wait(WorkItem item,string reason,string? comment,string? evidenceReference,DateTimeOffset? expectedDate,long actor,DateTimeOffset now){if(Status!=TicketStatus.InProgress)throw new InvalidOperationException("Ticket must be executing before waiting.");item.Wait(reason,comment,evidenceReference,expectedDate,now);Status=TicketStatus.Waiting;Record("WORK_ITEM_WAITING",actor,TicketStatus.InProgress.ToString(),TicketStatus.Waiting.ToString(),now,item.Id,reason);}
 public void Resume(WorkItem item,long actor,DateTimeOffset now){if(Status!=TicketStatus.Waiting)throw new InvalidOperationException("Ticket is not waiting.");item.Resume(now);Status=TicketStatus.InProgress;Record("WORK_ITEM_RESUMED",actor,TicketStatus.Waiting.ToString(),TicketStatus.InProgress.ToString(),now,item.Id);}
 public void CompleteWork(WorkItem item,long actor,DateTimeOffset now){item.Complete(now);Record("WORK_ITEM_COMPLETED",actor,"IN_PROGRESS","COMPLETED",now,item.Id);}
 public void AddEvidence(long actor,DateTimeOffset now){if(Status!=TicketStatus.InProgress)throw new InvalidOperationException("Evidence can be added during execution only.");_evidenceCount++;Record("EVIDENCE_CREATED",actor,null,_evidenceCount.ToString(),now);}
 public void Resolve(long actor,DateTimeOffset now){if(Status!=TicketStatus.InProgress||_evidenceCount==0)throw new InvalidOperationException("Execution must be active and evidence must exist before resolution.");if(_workItems.Any(x=>x.Status!="COMPLETED"))throw new InvalidOperationException("All work items must be completed before resolution.");var old=Status;Status=TicketStatus.Resolved;ResolvedAt=now;Record("TICKET_RESOLVED",actor,old.ToString(),Status.ToString(),now);}
 public void Reopen(string reason,long actor,DateTimeOffset now){if(Status is not(TicketStatus.Resolved or TicketStatus.Closed))throw new InvalidOperationException("Only resolved or closed tickets can be reopened.");if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Reopen reason is required.");var old=Status;Status=TicketStatus.Reopened;ResolvedAt=null;ClosedAt=null;Record("TICKET_REOPENED",actor,old.ToString(),Status.ToString(),now,reason:reason);}
 public void Cancel(string reason,long actor,DateTimeOffset now){if(Status is TicketStatus.Closed or TicketStatus.Resolved or TicketStatus.Cancelled)throw new InvalidOperationException("This ticket cannot be cancelled in its current state.");if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Cancellation reason is required.");var old=Status;Status=TicketStatus.Cancelled;Record("TICKET_CANCELLED",actor,old.ToString(),Status.ToString(),now,reason:reason);}
 public void Close(long actor,DateTimeOffset now){if(Status!=TicketStatus.Resolved)throw new InvalidOperationException("Only resolved tickets can be closed.");var old=Status;Status=TicketStatus.Closed;ClosedAt=now;Record("TICKET_CLOSED",actor,old.ToString(),Status.ToString(),now);}
 public void ValidateSpecializedStatusTransition(TicketStatus status){if(status is not(TicketStatus.Resolved or TicketStatus.Closed or TicketStatus.Reopened))throw new ArgumentException("The specialized workflow status is not supported.",nameof(status));if(Status==TicketStatus.Cancelled)throw new InvalidOperationException("Cancelled tickets are immutable.");if(status==TicketStatus.Resolved&&Status is (TicketStatus.Resolved or TicketStatus.Closed))throw new InvalidOperationException("A resolved or closed ticket cannot transition back to resolved.");if(status==TicketStatus.Closed&&Status!=TicketStatus.Resolved)throw new InvalidOperationException("Only resolved tickets can be closed.");if(status==TicketStatus.Reopened&&Status is not(TicketStatus.Resolved or TicketStatus.Closed))throw new InvalidOperationException("Only resolved or closed tickets can be reopened.");}
 public void TransitionSpecializedStatus(TicketStatus status,long actor,DateTimeOffset now,string? reason){ValidateSpecializedStatusTransition(status);var old=Status;Status=status;if(status==TicketStatus.Resolved)ResolvedAt=now;else if(status==TicketStatus.Closed)ClosedAt=now;else{ResolvedAt=null;ClosedAt=null;}Record("TICKET_STATUS_CHANGED",actor,old.ToString(),status.ToString(),now,reason:reason);}
 public void ClearEvents()=>_events.Clear();
 public static Ticket Restore(long id,string number,TicketType type,TicketStatus status,long requestedBy,long createdBy,string subject,string? description,long? serviceId,long? categoryId,long? requestTypeId,long? priorityId,long? currentDept,long? currentTeam,long? currentAssignee,DateTimeOffset createdAt,DateTimeOffset? resolvedAt,DateTimeOffset? closedAt,bool approvalRequired,bool approved,int evidenceCount,long? lastExecutor,IEnumerable<WorkItem> workItems,long? clientId=null,int? requestTypeVersion=null,long? subCategoryId=null,long? approvalApproverUserId=null,int rowVersion=0)
 {
    var t=new Ticket{Id=id,Number=number,Type=type,Status=status,RequestedBy=requestedBy,CreatedBy=createdBy,Subject=subject,Description=description,ServiceId=serviceId,CategoryId=categoryId,SubCategoryId=subCategoryId,RequestTypeId=requestTypeId,RequestTypeVersion=requestTypeVersion,ClientId=clientId,PriorityId=priorityId,CurrentDepartmentId=currentDept,CurrentTeamId=currentTeam,CurrentAssignee=currentAssignee,CreatedAt=createdAt,ResolvedAt=resolvedAt,ClosedAt=closedAt,_approvalRequired=approvalRequired,_approved=approved,_evidenceCount=evidenceCount,_lastExecutor=lastExecutor,_approvalApproverUserId=approvalApproverUserId,RowVersion=rowVersion};
  t._workItems.AddRange(workItems); return t;
 } private void EnsureMutable(){if(Status is TicketStatus.Closed or TicketStatus.Cancelled)throw new InvalidOperationException("Closed or cancelled tickets are immutable.");}
 private void Record(string action,long actor,string? oldValue,string? newValue,DateTimeOffset now,long? workItemId=null,string? reason=null)=>_events.Add(new(action,Id,actor,oldValue,newValue,now,workItemId,reason));
}
